package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each sheet's settings: the roles given to user names, its clerk limit, its floor and its terms. */
@Repository
public class Settings {

    /** The floor of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms, in days, of a sheet that has not set them. */
    public static final int DEFAULT_TERMS = 14;

    private final JdbcTemplate jdbc;

    public Settings(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The user's role on the sheet: a clerk unless given another. */
    public Role role(String sheetId, String user) {
        return jdbc.query("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                (rs, i) -> Role.valueOf(rs.getString("role")), sheetId, user)
                .stream().findFirst().orElse(Role.CLERK);
    }

    /** Every role given on the sheet, by user name. */
    public List<RoleResponse> roles(String sheetId) {
        return jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).show()),
                sheetId);
    }

    public void setRole(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }

    /** The sheet's clerk limit, or null for no limit. */
    public BigDecimal clerkLimit(String sheetId) {
        return column("clerk_limit", sheetId);
    }

    public void setClerkLimit(String sheetId, BigDecimal limit) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, clerk_limit) KEY (sheet_id) VALUES (?, ?)", sheetId, limit);
    }

    /** The sheet's floor: a claim's live due is at least it. 1.00 unless set. */
    public BigDecimal floor(String sheetId) {
        BigDecimal floor = column("floor", sheetId);
        return floor != null ? floor : DEFAULT_FLOOR;
    }

    public void setFloor(String sheetId, BigDecimal floor) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, floor) KEY (sheet_id) VALUES (?, ?)", sheetId, floor);
    }

    /** The sheet's terms: a claim is due by its date plus this many days. 14 unless set. */
    public int terms(String sheetId) {
        BigDecimal terms = column("terms", sheetId);
        return terms != null ? terms.intValue() : DEFAULT_TERMS;
    }

    public void setTerms(String sheetId, int terms) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, terms) KEY (sheet_id) VALUES (?, ?)", sheetId, terms);
    }

    /** One setting's stored value, null when the sheet has no row or the setting is unset. */
    private BigDecimal column(String column, String sheetId) {
        List<BigDecimal> values = jdbc.query("SELECT " + column + " FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getBigDecimal(column), sheetId);
        return values.isEmpty() ? null : values.get(0);
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {
    /** An amount: 0.00 or more, with up to two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");

    /** Terms: a whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest request,
            Out<SettingsChange> change, Out<Actor> actor) throws InvalidSheetRequestException {
        String limit = request == null || request.clerkLimit() == null ? null : request.clerkLimit().trim();
        if (limit != null && !limit.isEmpty() && !AMOUNT.matcher(limit).matches()) {
            throw new InvalidSheetRequestException("The clerk limit must be an amount with up to two decimals, or blank");
        }
        String floor = request == null || request.floor() == null ? null : request.floor().trim();
        if (floor != null && !floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
            throw new InvalidSheetRequestException("The floor must be an amount with up to two decimals, or blank");
        }
        String terms = request == null || request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new InvalidSheetRequestException("The terms must be a whole number of days, or blank");
        }
        String by = request == null ? null : request.user();
        actor.set(new Actor(by));
        change.set(new SettingsChange(sheetId, limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor == null ? null : floor.isEmpty() ? Settings.DEFAULT_FLOOR : new BigDecimal(floor).setScale(2),
                terms == null ? null : terms.isEmpty() ? Settings.DEFAULT_TERMS : Integer.parseInt(terms),
                by));
    }
}
package net.officefloor.hq.app.settings;

/** Body of a settings change: the settings being set, each left out (null) when it is not being
 *  changed — the clerk limit (two decimals, blank for no limit), the floor (two decimals, blank for
 *  the default 1.00), the terms (whole days, blank for the default 14) — and who makes the change. */
public record SettingsRequest(String clerkLimit, String floor, String terms, String user) {
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;

/** A validated settings change on a sheet: whether the clerk limit is set and to what (null for no
 *  limit), the floor and the terms, each null when it is not being set. */
public record SettingsChange(String sheetId, boolean setsClerkLimit, BigDecimal clerkLimit, BigDecimal floor, Integer terms, String by) {
}
package net.officefloor.hq.app.settings;

import net.officefloor.plugin.variable.Val;

public class SaveSettings {
    public void save(@Val SettingsChange change, Settings settings) {
        if (change.setsClerkLimit()) settings.setClerkLimit(change.sheetId(), change.clerkLimit());
        if (change.floor() != null) settings.setFloor(change.sheetId(), change.floor());
        if (change.terms() != null) settings.setTerms(change.sheetId(), change.terms());
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the settings are saved, so a refused change writes no audit line. A line per setting set. */
public class RecordSettingChanged {
    public void record(@Val SettingsChange change, Audit audit) {
        String prefix = "SETTING_CHANGED sheet=" + change.sheetId() + " by=" + change.by();
        if (change.setsClerkLimit()) {
            audit.record(prefix + " key=clerk-limit value="
                    + (change.clerkLimit() != null ? change.clerkLimit().toPlainString() : ""));
        }
        if (change.floor() != null) {
            audit.record(prefix + " key=floor value=" + change.floor().toPlainString());
        }
        if (change.terms() != null) {
            audit.record(prefix + " key=terms value=" + change.terms());
        }
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.List;

